  static List<Recipe> get featuredRecipes => recipes.where((r) => r.isFeatured).toList();
  static List<Recipe> get favoriteRecipes => recipes.where((r) => r.isFavorite).toList();

  static List<Recipe> byCategory(RecipeCategory cat) => recipes.where((r) => r.category == cat).toList();

  static List<Recipe> search(String query) {
    final q = query.toLowerCase();
    return recipes.where((r) =>
      r.title.toLowerCase().contains(q) ||
      r.description.toLowerCase().contains(q) ||
      r.tags.any((t) => t.toLowerCase().contains(q))
    ).toList();
  }

  static const List<RecipeCategory> allCategories = RecipeCategory.values;
